import {resourceError} from './resource-error.mjs';
import React,{useState} from 'react';
import {useResource} from './state.js';
export function AppearancePlan({call,novelId,nodeId,onChapter,refresh}){
 const [poll,setPoll]=useState(0),[editing,setEditing]=useState(false),[value,setValue]=useState({}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const r=useResource(()=>Promise.all([call('graph.get',{novelId,nodeId}),call('chapter.list',{novelId})]),[call,novelId,nodeId,poll]);if(!r.value)return <div><p role={r.error?'alert':'status'}>{r.error?resourceError(r.error):'读取出场安排…'}</p>{r.error&&<button type="button" onClick={r.retry}>重试读取出场安排</button>}</div>;
 const [node,chapters]=r.value,p=node.appearancePlan,change=(key,v)=>setValue(old=>({...old,[key]:v}));
 return <section className="profile-chapters">{r.error&&<p role="alert">{resourceError(r.error)}<button type="button" onClick={r.retry}>重试</button></p>}<header className="profile-block-heading"><h4>计划首次出场</h4><button onClick={()=>{setValue(p||{});setEditing(!editing);}}>{editing?'取消':'安排出场'}</button></header><p className="profile-caption">资料可以提前写完整。计划与正式出场分别记录，仅被提及不会让人物提前出场。</p>{!editing?<p>{p?.chapterId?<button onClick={()=>onChapter?.(p.chapterId)}>{chapters.find(c=>c.id===p.chapterId)?.title||'原章节已删除'}</button>:'叙述位置未安排'} · {p?.dateText||(Number.isFinite(p?.story)?'故事时间 '+p.story:'故事时间未定')}</p>:<div className="structure-form"><label>计划章节<select value={value.chapterId||''} onChange={e=>change('chapterId',e.target.value||null)}><option value="">暂不安排</option>{chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>故事坐标<input type="number" step="any" value={value.story??''} onChange={e=>change('story',e.target.value===''?null:Number(e.target.value))}/></label><label>日期／时期<input maxLength={200} value={value.dateText||''} onChange={e=>change('dateText',e.target.value)}/></label><button disabled={busy} onClick={async()=>{setBusy(true);setError('');try{await call('graph.update',{novelId,nodeId,expectedRevision:node.revision,appearancePlan:value,reason:'安排计划首次出场'});setEditing(false);setPoll(n=>n+1);refresh?.();}catch(e){setError(resourceError(e));}finally{setBusy(false);}}}>保存计划</button></div>}{error&&<p role="alert">{error}</p>}</section>;
}
